    def _load_baseline(self) -> str:
        """Previous stage's app: keep its routes and archived gates; describe it to the planner."""
        root = self.workspace.root
        app = (root / 'frontend/src/App.tsx').read_text(errors='replace')
        imports = dict(re.findall(r"import (\w+) from '\./([^']+)';", app))
        for path, component in re.findall(r'<Route path="([^"]+)" element=\{<(\w+) />\}', app):
            module = imports.get(component)
            if not module:
                continue
            file = 'frontend/src/' + module + ('' if module.endswith(('.tsx', '.ts', '.jsx', '.js')) else '.tsx')
            if not (root / file).exists() and (root / ('frontend/src/' + module + '.ts')).exists():
                file = 'frontend/src/' + module + '.ts'
            self.shared.routes.append({'path': path, 'file': file, 'unit': 'baseline'})
        archive = root / 'backend' / 'test-archive'
        restored = 0
        if archive.is_dir():
            target = root / 'backend' / 'test-e2e'
            target.mkdir(parents=True, exist_ok=True)
            for index, spec in enumerate(sorted(archive.glob('*acc-gate*.spec.js'))):
                shutil.copy2(spec, target / f'acc-prev{index}-acc-gate.spec.js')
                restored += 1
        files = sorted(str(p.relative_to(root)) for folder in ('backend/src', 'frontend/src') for p in (root / folder).rglob('*')
                       if p.is_file() and p.suffix in {'.js', '.ts', '.tsx'})
        endpoints = []
        for route_file in sorted((root / 'backend/src/routes').glob('*.js')):
            for method, path in re.findall(r"router\.(get|post|put|patch|delete)\(\s*['\"]([^'\"]+)", route_file.read_text(errors='replace')):
                endpoints.append(f'{method.upper()} /api{path}')
        event('baseline', {'routes': len(self.shared.routes), 'files': len(files), 'endpoints': len(endpoints), 'archived_gates': restored})
        return ('\n\nEXISTING APPLICATION (built by the previous stage; it already passes earlier requirements and is the starting point). '
                'EXTEND it: keep every existing page, route, API endpoint, seed record and behaviour; plan units only for the NEW requirements above; '
                'new units own NEW files; when a feature must change an existing file it does so with small edit_file edits. '
                'Reuse existing modules, auth, layout and data collections instead of re-creating them.\n'
                'Existing client routes: ' + ', '.join(f"{r['path']} -> {r['file']}" for r in self.shared.routes)[:3000] + '\n'
                'Existing API endpoints: ' + ', '.join(endpoints)[:4000] + '\n'
                'Existing source files: ' + ', '.join(files)[:5000] + '\n')

    def materialize_plan(self) -> None:
        for unit in self.blueprint['units']:
            for file in unit['files']:
                self.shared.owner[file] = unit['id']
        layout = self.workspace.root / 'frontend/src/components/Layout.tsx'
        if not layout.exists():
            layout.parent.mkdir(parents=True, exist_ok=True)
            text = "import { Outlet } from 'react-router-dom';\n\nexport default function Layout() {\n  return <Outlet />;\n}\n"
            layout.write_text(text)
            self.shared.stubs['frontend/src/components/Layout.tsx'] = text
        seen_paths = set()
        for route in self.blueprint['routes']:
            if route['path'] in seen_paths:
