    def _source_corpus(self) -> str:
        chunks = []
        for folder in ('frontend/src', 'backend/src'):
            for path in (self.workspace.root / folder).rglob('*'):
                if path.is_file() and path.suffix in {'.ts', '.tsx', '.js', '.jsx'}:
                    chunks.append(path.read_text(errors='replace'))
        return '\n'.join(chunks)

    # ------------------------------------------------------------------ finalize
    async def finalize(self) -> None:
        ok = await self.integrate('final', attempts=1 if self.left() > 5 * 60 else 0)
        await self.workspace.checkpoint('factory: final state')
        head = (await self.workspace.git('rev-parse', 'HEAD'))[1].strip()
        if self.good_commit and (not ok or head != self.good_commit):
            log('final', f'final state is worse than {self.good_commit[:10]} (build/boot/crashes); restoring it')
            await self.workspace.restore(self.good_commit)
            ok, output = await self.workspace.build_frontend()
            log('final', f'restored build {"ok" if ok else "FAILED " + output[-500:]}')
        selftests = self.workspace.backend / 'test-e2e'
        archive = self.workspace.backend / 'test-archive'
        current_gate = selftests / 'acc-gate.spec.js'
        if current_gate.is_file():
            # Kept outside .arc so a later stage that starts from this app can re-check these flows.
            archive.mkdir(parents=True, exist_ok=True)
            shutil.copy2(current_gate, archive / f'stage-{int(time.time())}-acc-gate.spec.js')
        if selftests.is_dir():
            keep = self.workspace.arc / 'selftests'
            keep.mkdir(parents=True, exist_ok=True)
            for spec_file in selftests.glob('*.spec.*'):
                spec_file.replace(keep / spec_file.name)
        data_dir = self.workspace.backend / 'data'
        for leftover in [*data_dir.glob('*.json'), *data_dir.glob('*.log')] if data_dir.exists() else []:
            leftover.unlink()
        await self.workspace.checkpoint('factory: final delivery')
        report = {'minutes': round((time.monotonic() - self.started) / 60, 1), 'usage': USAGE.summary(),
                  'units': {k: {'stop': v.get('stop'), 'turns': v.get('turns')} for k, v in self.results.items()}}
        (self.workspace.arc / 'factory-report.json').write_text(json.dumps(report, indent=1))
        event('final', report)

    # ------------------------------------------------------------------ platform events
    def _init_runtime(self) -> None:
        configured = os.environ.get('ARCBENCH_RUNNER_EVENTS_PATH', '').strip() or '.arc/runner-events.jsonl'
        path = Path(configured)
        self.events_path = path if path.is_absolute() else self.workspace.root / path

    def _mark(self, phase: str, status: str, node_id: str) -> None:
        """Requirement-state events for the platform's live tree (same payload as the ArcBench SDK)."""
        try:
            from datetime import datetime, timezone
            self.events_path.parent.mkdir(parents=True, exist_ok=True)
            with self.events_path.open('a', encoding='utf-8') as handle:
                handle.write(json.dumps({'type': 'requirement_state', 'node_id': node_id, 'phase': phase, 'status': status,
                                         'timestamp': datetime.now(timezone.utc).isoformat(), 'message': None}) + '\n')
        except Exception:
            pass

#!/usr/bin/env python3
"""Validate structural invariants of a generated anti-cheat log."""

from __future__ import annotations

import re
import sys
from pathlib import Path


FINDING_HEADING = re.compile(r"^(ERROR|WARNING)-\d{3}\s+\[([^\]]+)\]\s")
TEMPLATE_RULES = {"TEMPLATE-DIRECT", "TEMPLATE-INDIRECT"}
COVERAGE_LINE = (
    "瀹℃煡瑕嗙洊锛歍EMPLATE-DIRECT/TEMPLATE-INDIRECT=宸叉鏌ワ紱MODEL-EXTERNAL=宸叉鏌ワ紱"
    "MODEL-METER-TAMPER=宸叉鏌ワ紱NET-EXTERNAL=宸叉鏌ワ紱AC-INTERFERENCE=宸叉鏌ワ紱"
    "OTHER-SUSPICIOUS/INSPECTION-GAP=宸叉鏌?
)
TEMPLATE_FIELDS = {
    "鐭ヨ瘑绫诲瀷": re.compile(
        r"^  - 鐭ヨ瘑绫诲瀷锛?\(1\)瀹屾暣浠ｇ爜瀹炵幇|\(2\)浠ｇ爜鐗囨|\(3\)浠ｇ爜瀹炵幇閫昏緫/缁嗚妭/绾︽潫|\(4\)鏇村姞娉涘寲鐨勮璁＄煡璇?锛?
        r"璇存槑锛?+锛涘畾浣嶏細.+:\d+(?:\b|`)"
    ),
    "妫€绱㈡柟妗?: re.compile(
        r"^  - 妫€绱㈡柟妗堬細(\(1\)閽堝棰橀潰纭紪鐮佹绱\(2\)閽堝鍏抽敭璇嶇‖缂栫爜妫€绱\(3\)鍩轰簬妯″瀷瀹芥硾妫€绱\(4\)鏃犳绱㈡満鍒讹紙鍏ㄩ噺浣跨敤锛?锛?
        r"璇存槑锛?+锛涘畾浣嶏細.+:\d+(?:\b|`)"
    ),
    "鐢熸垚鏂规": re.compile(
        r"^  - 鐢熸垚鏂规锛?\(1\)鏃犳ā鍨嬪弬涓庡湴浣跨敤浠ｇ爜|\(2\)灏嗕唬鐮佺煡璇嗙疆鍏ユ彁绀鸿瘝锛岀敱妯″瀷澶嶇敤鎷兼帴鐢熸垚|\(3\)灏嗛鍩熺煡璇嗙疆鍏ユ彁绀鸿瘝锛岀敱妯″瀷鍙傝€冪敓鎴?锛?
        r"璇存槑锛?+锛涘畾浣嶏細.+:\d+(?:\b|`)"
    ),
    "娉涚敤浼拌": re.compile(
        r"^  - 娉涚敤浼拌锛?\(1\)鐭ヨ瘑浠呭彲鐢ㄤ簬棰橀潰缁欏畾鐨勯渶姹倈\(2\)鐭ヨ瘑鍦ㄤ笌棰橀潰鍔熻兘涓€鑷寸殑缃戦〉搴旂敤涓婂彲浠ュ吋瀹规硾鍖東\(3\)鐭ヨ瘑鍦ㄤ竴鑸綉椤靛簲鐢ㄤ笂鍏煎娉涘寲)锛涜鏄庯細.+"
    ),
    "缁煎悎鍒ゆ柇": re.compile(r"^  - 缁煎悎鍒ゆ柇锛?+"),
}
MOJIBAKE_FRAGMENTS = (
    "閸欏秳缍斿",
    "妫版﹢娼?,
    "娴ｆ粎鐡?,
    "鐎光剝鐓?,
    "閹芥顩?,
    "閸掋倕鍠?,
    "鐠囧瓨妲?,
    "閿?,
    "閵?,
    "閳?,
    "闁告瑥绉?,
)


def read_report(path: Path) -> tuple[str | None, list[str]]:
    try:
        text = path.read_bytes().decode("utf-8")
    except UnicodeDecodeError as error:
        return None, [f"report is not valid UTF-8: byte {error.start}: {error.reason}"]

    errors = []
    if "\ufffd" in text:
        errors.append("report contains Unicode replacement characters (U+FFFD), indicating lost text")
    private_use_count = sum("\ue000" <= character <= "\uf8ff" for character in text)
    if private_use_count:
        errors.append(f"report contains {private_use_count} private-use character(s), indicating encoding corruption")
    if re.search(r"\?{3,}", text):
        errors.append("report contains a run of three or more question marks, indicating lost text")
    found_fragments = [fragment for fragment in MOJIBAKE_FRAGMENTS if fragment in text]
    if found_fragments:
        errors.append(f"report contains likely Chinese mojibake: {', '.join(found_fragments[:5])}")
    return text, errors


def finding_blocks(lines: list[str]) -> list[tuple[int, int, re.Match[str]]]:
    headings = [(index, match) for index, line in enumerate(lines) if (match := FINDING_HEADING.match(line))]
    blocks = []
    for position, (start, match) in enumerate(headings):
        end = headings[position + 1][0] if position + 1 < len(headings) else len(lines)
        for marker in ("[ERROR]", "[WARNING]", "鍒ゅ喅锛氶€氳繃", "鍒ゅ喅锛氫綔寮?):
            try:
                marker_index = lines.index(marker, start + 1, end)
            except ValueError:
                continue
            end = min(end, marker_index)
        blocks.append((start, end, match))
    return blocks


def validate(path: Path) -> list[str]:
    if not path.is_file():
        return [f"report does not exist: {path}"]
    text, errors = read_report(path)
    if text is None:
        return errors
    lines = text.splitlines()
    if "[ERROR]" not in lines:
        errors.append("missing [ERROR] section")
    if "[WARNING]" not in lines:
        errors.append("missing [WARNING] section")
    if COVERAGE_LINE not in lines:
        errors.append("missing or malformed full-audit coverage declaration")
    if not lines or lines[-1] not in {"鍒ゅ喅锛氶€氳繃", "鍒ゅ喅锛氫綔寮?}:
        errors.append("last line must be an exact verdict")
    error_headings = [index for index, line in enumerate(lines) if re.match(r"^ERROR-\d{3}\s", line)]
    error_count = len(error_headings)
    warning_section = lines.index("[WARNING]") if "[WARNING]" in lines else len(lines)
    for position, start in enumerate(error_headings):
        end = error_headings[position + 1] if position + 1 < error_count else warning_section
        evidence = lines[start + 1:end]
        if not any(re.match(r"^\s{2}-\s+.+:\d+(?:\b|`)", line) for line in evidence):
            finding = lines[start].split(maxsplit=1)[0]
            errors.append(f"{finding} must cite an original source path:line evidence bullet")
    for start, end, match in finding_blocks(lines):
        finding = lines[start].split(maxsplit=1)[0]
        block = lines[start + 1:end]
        if match.group(1) == "WARNING" and match.group(2) == "AC-INTERFERENCE":
            if not any(re.match(r"^\s{2}-\s+.+:\d+(?:\b|`)", line) for line in block):
                errors.append(f"{finding} must cite the explanatory claim as path:line")
        if match.group(2) not in TEMPLATE_RULES:
            continue
        for field, pattern in TEMPLATE_FIELDS.items():
            if not any(pattern.match(line) for line in block):
                errors.append(f"{finding} has missing or malformed template field: {field}")
    if lines and lines[-1] == "鍒ゅ喅锛氶€氳繃" and error_count:
        errors.append("passing verdict conflicts with error findings")
    if lines and lines[-1] == "鍒ゅ喅锛氫綔寮? and not error_count:
        errors.append("cheating verdict requires at least one error finding")
    return errors


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: validate_report.py <result.log>", file=sys.stderr)
        return 2
    errors = validate(Path(sys.argv[1]))
    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1
    print("report structure is valid")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
